// th14_s4_w11 — TH14 v1.00b 四面道中，st04.ecl.txt MainSub06 局部入口 1217–1239。
// 源敌闭包：GirlD01(673–695, 697–741)、ECir00(12–45, 47–146)。
// 弹型按 transcribe/th14/touhou-bullets.ecl 合成映射：源 type8/4 → TH14_RICE/TH14_BALL。

const TIME_LIMIT: int = 2424;
const OPENING_BUFFER: int = 120;

const TH14_BALL: int = 416;
const TH14_RICE: int = 480;

// 源弧度换 BAM：0.349066→3641，0.10471976→1092，0.31415927→3277，0.05235988→546（半角273）。
const GIRL_OFFSET_ANGLE: int = 3641;
const GIRL_ANGLE_JITTER: int = 1092;
const DESCENT_ANGLE: int = 16384;
const MODE8_ANGLE_AMP: int = 3277;
const MODE1_HALF_SPREAD: int = 273;

// ── 独立无敌外壳（control 只承担段事件） ──────────────────────────────────
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// ── 排程：MainSub06 1217–1239（源卡帧 0） ────────────────────────────────
async sub pattern() {
    wait(OPENING_BUFFER);
    // 1217–1218
    _ = spawn_enemy(96fx, -32fx, 800, 0, 0, 0, source_girl_d);
    _ = spawn_enemy(-96fx, -32fx, 800, 0, 0, 0, source_girl_d);
    wait(40);                       // 1219
    // 1220–1228：7 只 ECir，x=0,-10,…,-60，间隔 20
    var ax: fx = 0fx;
    for i in 0..7 {
        _ = spawn_enemy(ax, 0fx, 150, 0, 0, 0, source_ecir(ax, 1));
        wait(20);
        ax = ax - 10fx;
    }
    wait(130);                      // 1229
    // 1230
    _ = spawn_enemy(0fx, -32fx, 800, 0, 0, 0, source_girl_d);
    // 1231–1239：10 组，镜像/普通交替，各 15 帧
    for k in 0..10 {
        _ = spawn_enemy(0fx, 0fx, 150, 0, 0, 0, source_ecir(0fx, -1));
        wait(15);
        _ = spawn_enemy(0fx, 0fx, 150, 0, 0, 0, source_ecir(0fx, 1));
        wait(15);
    }
}

// ── GirlD01 673–695 ──────────────────────────────────────────────────────
async sub source_girl_d() {
    set_invuln(65535);
    set_hurtbox(16fx);              // 681: 32×0.5
    set_hitbox(12fx);               // 682: 24×0.5
    move_vel(0, 90deg, 1.4fx, EASE_LINEAR);      // 683
    move_speed(60, 0fx, EASE_QUAD_IN);           // 684: mode1
    spawn girl_attack();                         // 685
    wait(120);                                   // 686
    move_speed(80, 1fx, EASE_QUAD_IN);           // 687: mode1
    wait(60);                                    // 688
    loop { wait(1000); }
}

// ── GirlD01_at 697–741 ───────────────────────────────────────────────────
async sub girl_attack() {
    wait(60);                       // 700
    var rank: int = global(GVAR_RANK);
    var loops: int = 1;             // 708 diffI(E,N,H,L)=1,2,3,4
    if rank == 1 { loops = 2; }
    if rank == 2 { loops = 3; }
    if rank >= 3 { loops = 4; }
    var gap: int = 4;               // 726–734: E4/N3/H2/L1
    if rank == 1 { gap = 3; }
    if rank == 2 { gap = 2; }
    if rank >= 3 { gap = 1; }

    for a in 0..loops {
        // 711–713：每轮外层重置
        var b: int = GIRL_OFFSET_ANGLE;
        var c: fx = 8fx;
        for d in 0..15 {
            // 716–719：偏移角随机 → 弹角随机 → 弹速随机
            var u1: int = rand(65536) - 32768;
            var oa1: angle = (b * u1 / 32768) as angle;
            var j1: int = rand(65536) - 32768;
            var dir1: angle = (DESCENT_ANGLE + j1 * GIRL_ANGLE_JITTER / 32768) as angle;
            var q1: fx = ((rand(65536) - 32768) as fx / 65536) + 0.5fx;
            var sp1: fx = q1 * 1.5fx + 1fx;
            // etEx type2 ANIM a=1：出生退位移 position -= 4*velocity
            _ = fire(TH14_RICE, 6,
                     $self_x + c * cos(oa1) - 4fx * sp1 * cos(dir1),
                     $self_y + c * sin(oa1) - 4fx * sp1 * sin(dir1),
                     sp1, dir1, none, none);

            var u2: int = rand(65536) - 32768;
            var oa2: angle = (b * u2 / 32768) as angle;
            var j2: int = rand(65536) - 32768;
            var dir2: angle = (DESCENT_ANGLE + j2 * GIRL_ANGLE_JITTER / 32768) as angle;
            var q2: fx = ((rand(65536) - 32768) as fx / 65536) + 0.5fx;
            var sp2: fx = q2 * 1.5fx + 1fx;
            _ = fire(TH14_RICE, 6,
                     $self_x - c * cos(oa2) - 4fx * sp2 * cos(dir2),
                     $self_y - c * sin(oa2) - 4fx * sp2 * sin(dir2),
                     sp2, dir2, none, none);

            c = c + 10fx;           // 724
            b = b * 98 / 100;       // 725
            wait(gap);              // 735
        }
    }
}

// ── ECir00 12–45 ─────────────────────────────────────────────────────────
async sub source_ecir(sx: fx, dir: int) {
    set_invuln(65535);
    set_hurtbox(12fx);              // 21: 24×0.5
    set_hitbox(8fx);                // 22: 16×0.5
    set_enemy_flag(ENEMY_NO_BODY, 1);        // 26 flagSet(15) 的体碰位
    // 32 movePosRel：REL 层瞬间到 sx-192A（出生帧后立即生效）
    var x0: fx = sx - 192fx * dir;
    move_to(0, x0, 0fx, EASE_LINEAR);
    // 33 moveBezierRel(120, 256A,-30, 160A,128, 0,0)：mode8 Hermite 端点和切线
    var x1: fx = x0 + 160fx * dir;
    hermite_start(0, x0, x1, 256fx * dir, 0fx, 120);
    hermite_start(1, 0fx, 128fx, -30fx, 0fx, 120);
    for st in 0..120 {
        wait(1);
        move_to(1, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    set_enemy_flag(ENEMY_NO_BODY, 0);        // 35 flagClear(15)
    // 37 moveBezierRel(120, 0,0, -220A,192, -200A,-228)
    var x2: fx = x1 - 220fx * dir;
    hermite_start(0, x1, x2, 0fx, -200fx * dir, 120);
    hermite_start(1, 128fx, 320fx, 0fx, -228fx, 120);
    spawn ecir_attack();            // 38：第二段行进中开火
    for en in 0..120 {
        wait(1);
        move_to(1, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    loop { wait(1000); }
}

// ── ECir00_at 47–146 ─────────────────────────────────────────────────────
async sub ecir_attack() {
    wait(10);                       // 50
    var rank: int = global(GVAR_RANK);
    var shots: int = 1;             // 83 diffI(E,N,H,L)=1,1,1,8
    if rank >= 3 { shots = 8; }
    var lspd: fx = 2.7fx;           // 54–61 / 64–69
    var llen: fx = 128fx;           // 72–79
    if rank == 1 { lspd = 3.5fx; }
    if rank == 2 { lspd = 4.5fx; llen = 144fx; }
    if rank >= 3 { lspd = 5.0fx; llen = 160fx; }
    var gap: int = 600;             // 133–141
    if rank == 1 { gap = 50; }
    if rank == 2 { gap = 10; }
    if rank >= 3 { gap = 8; }
    var nrand: int = 1;             // 92–100
    if rank == 1 { nrand = 3; }
    if rank >= 2 { nrand = 5; }
    var amp: fx = 2.0fx;            // 103–111
    if rank == 1 { amp = 2.5fx; }
    if rank >= 3 { amp = 3.0fx; }

    for i in 0..shots {
        // 700/702：初长0→目标长L，速度=源 etSpeed；宽度14按恒宽近似取7（laser_approx）
        var h: int = laser(3, $self_x, $self_y, aim_player(), llen, 7fx, 0, 9999, 0);
        lz_speed(h, lspd, llen);
        if rank >= 1 {
            // 89–114 etAim(1,8)：每颗先角随机 ±18°，再速随机 1..1+amp
            var base: angle = aim_player();
            for k in 0..nrand {
                var ju: int = rand(65536) - 32768;
                var ang: angle = (((base as int) + ju * MODE8_ANGLE_AMP / 32768) as angle);
                var qu: fx = ((rand(65536) - 32768) as fx / 65536) + 0.5fx;
                var sp: fx = 1fx + qu * amp;
                _ = fire(TH14_BALL, 8,
                         $self_x - 4fx * sp * cos(ang),
                         $self_y - 4fx * sp * sin(ang),
                         sp, ang, none, none);
            }
            // 115–131 etAim(1,1)：固定方向双路，±0.05235988/2
            var aim2: angle = aim_player();
            var a1: angle = (((aim2 as int) + MODE1_HALF_SPREAD) as angle);
            var a2: angle = (((aim2 as int) - MODE1_HALF_SPREAD) as angle);
            _ = fire(TH14_BALL, 8, $self_x - 8fx * cos(a1), $self_y - 8fx * sin(a1),
                     2fx, a1, none, none);
            _ = fire(TH14_BALL, 8, $self_x - 8fx * cos(a2), $self_y - 8fx * sin(a2),
                     2fx, a2, none, none);
        }
        wait(gap);                  // 142
    }
}
